DRAGON_COLOR = {"black": "Negro", "blue": "Azul", "brass": "de Latão", "bronze": "de Bronze", "copper": "de Cobre", "gold": "Dourado",
	"green": "Verde", "red": "Vermelho", "silver": "Prateado", "white": "Branco"}


def dragon_names():
	out = {}
	for col, pt in DRAGON_COLOR.items():
		out[f"{col}_dragon_wyrmling"] = f"Filhote de Dragão {pt}"
		out[f"young_{col}_dragon"] = f"Dragão {pt} Jovem"
		out[f"adult_{col}_dragon"] = f"Dragão {pt} Adulto"
		out[f"ancient_{col}_dragon"] = f"Dragão {pt} Ancião"
	return out
